import { Controller } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Prescription } from '../entities/prescription.entity';

interface PrescriptionRequestPayload {
  prescriptionId: string;
  requesterId: string;
  requesterRole: 'PATIENT' | 'PRESCRIBER' | 'PHARMACIST';
}

@Controller()
export class RxMicroserviceController {
  constructor(
    @InjectRepository(Prescription)
    private readonly rxRepo: Repository<Prescription>,
  ) {}

  @MessagePattern('health.prescription.details')
  async getRx(@Payload() data: PrescriptionRequestPayload) {
    if (!data.requesterId || !data.requesterRole) {
      return { error: 'Authentication credentials required', status: 401 };
    }

    const rx = await this.rxRepo.findOne({
      where: { id: data.prescriptionId },
      relations: ['patient', 'doctor', 'medications']
    });

    if (!rx) {
      return { error: 'Prescription record not found', status: 404 };
    }

    // Assert authorization: only the patient, assigned doctor, or dispensing pharmacy
    const isPatient = data.requesterRole === 'PATIENT' && rx.patient.id === data.requesterId;
    const isPrescriber = data.requesterRole === 'PRESCRIBER' && rx.doctor.id === data.requesterId;
    const isPharmacist = data.requesterRole === 'PHARMACIST';

    if (!isPatient && !isPrescriber && !isPharmacist) {
      return { error: 'Access denied: unauthorized to inspect prescription', status: 403 };
    }

    return rx;
  }
}
